// Block (composition) — a read-only order identifier, status, and value breakdown.
import type { ReactNode, Ref } from "react";
import { Badge } from "../components/Badge";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import "./OrderSummary.css";

export interface OrderSummaryProps {
  orderId?: string;
  status?: string;
  lines: { label: string; value: string }[];
  total: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function OrderSummary({
  orderId,
  status,
  lines,
  total,
  className,
  ref,
}: OrderSummaryProps) {
  // The values end their rows under the status Badge's end edge, so with a status they take the end
  // inset (component-contract.md §6 rule 8). Without one no box shares that edge and they stay at 0.
  const valueText = (value: ReactNode) => (status ? <>{value}</> : value);

  return (
    <Stack
      as="section"
      ref={ref}
      gap="small"
      aria-label="Order summary"
      className={className ? `sd-ordersummary ${className}` : "sd-ordersummary"}
    >
      {(orderId || status) && (
        <>
          <Stack direction="row" align="center" justify="between" gap="small" className="sd-ordersummary__header">
            {orderId && (
              <h3 className="sd-ordersummary__order sd-type-title-medium">Order {orderId}</h3>
            )}
            {status && <Badge>{status}</Badge>}
          </Stack>
          <Separator />
        </>
      )}
      {lines.map((line) => (
        <Stack key={line.label} direction="row" justify="between" align="baseline" gap="small" className="sd-ordersummary__line">
          <span className="sd-ordersummary__label sd-type-label-medium">{line.label}</span>
          {valueText(<span className="sd-ordersummary__value sd-type-body-medium">{line.value}</span>)}
        </Stack>
      ))}
      <Separator />
      <Stack direction="row" justify="between" align="baseline" gap="small" className="sd-ordersummary__line">
        <span className="sd-ordersummary__total-label sd-type-label-medium">Total</span>
        {valueText(<span className="sd-ordersummary__total-value sd-type-headline-medium">{total}</span>)}
      </Stack>
    </Stack>
  );
}

/* OrderSummary.css — .sd-ordersummary (Block)
   Arrangement only: a compact read-only section that fills the column it is given. */
.sd-ordersummary {
  width: 100%;
}

.sd-ordersummary__order {
  margin: 0;
}

.sd-ordersummary__label {
  min-width: 0;
}

.sd-ordersummary__value {
  flex: none;
}
